  "contradictory_card_ids": ["C20", "C75"],
  "prediction_basis_card_ids": ["C03", "C10", "C67", "C70", "C71", "C77", "C68", "C72", "C74", "C16", "C25", "C27"],
  "claims": [
    {
      "claim": "Cebranopadol, the closest measured structural context with a fused indole, aryl fluoride, and basic amine, has fasted absolute oral bioavailability of about 40%, above the 20% threshold despite substantial first-pass metabolism.",
      "card_ids": ["C03", "C10"]
    },
    {
      "claim": "L6 human liver microsomal intrinsic clearance for the closest analog sharing the 4-(methylaminomethyl)phenyl motif is low, 4.2 to 8.7 ml/min/kg with and without NADPH, indicating limited hepatic first-pass loss.",
      "card_ids": ["C67", "C69", "C70", "C71", "C73", "C77"]
    },
    {
      "claim": "The lactam-fused indole analog M03 shows moderate human liver microsomal CLint of 66 µL/min/mg and moderate hepatocyte clearance in rat and dog, 39 and 32 µL/min per 10^6 cells, which is not an extreme first-pass liability.",
      "card_ids": ["C68", "C72", "C74"]
    },
    {
      "claim": "Vonoprazan L6 records show conflicting human microsomal CLint values of 2.73 and 90.9 µL/min/mg and substantial CYP3A4 metabolism, but the sulfonyl azole scaffold has low transferability to the query.",
      "card_ids": ["C75", "C76", "C78"]
    },
    {
      "claim": "Fasted-state absolute F values in humans for related small molecules are all above 20%: safinamide 95%, linezolid 93 to 100%, aprepitant 59 to 67%, and darolutamide 98.9% as an oral solution with one conflicting about 30% report.",
      "card_ids": ["C01", "C13", "C12", "C29", "C04", "C11", "C02", "C20"]
    },
    {
      "claim": "L5 Caco-2 records for close fused-lactam analogs with basic amine side chains show high permeability above 10 x 10^-6 cm/s and low efflux ratios of 2.27 and 1.75, indicating low gut-wall efflux; repeated entries are not independent evidence.",
      "card_ids": ["C62", "C58"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77", "C78"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No query-specific IV reference or matched fasted-state PK study.",
    "L6 records are analog microsome and hepatocyte assays, not direct F measurements; M03 HLM CLint is moderate and vonoprazan CLint values conflict.",
    "Darolutamide context has conflicting fasted F values of about 30% versus 98.9%, leaving formulation and dose dependence unresolved.",
    "Query has a very low neutral fraction and low logD, but no direct permeability measurement for the query is available.",
    "No query-specific intestinal metabolism data; gut-wall and hepatic first-pass contributions cannot be fully separated."
  ],
  "decision_summary": "Predicted high: F >= 20% is better supported. The closest measured structural context, cebranopadol, has fasted absolute F of about 40% despite substantial first-pass metabolism. L6 human liver microsomal intrinsic clearance for the closest analog sharing the methylaminomethyl-phenyl motif is low at 4 to 9 ml/min/kg, indicating limited hepatic first-pass loss, and the lactam-fused indole analog shows moderate rather than extreme clearance. Related fasted human F values are all above 20%. Confidence remains moderate because no direct query F measurement exists and first-pass metabolism cannot be fully excluded."
}

